// ── Timezone calling hours checker ─────────────────────────────────────────
// Maps phone country code → IANA timezone (most populated/common zone)
const COUNTRY_CODE_TZ = {
  '+1':   'America/New_York',      // US/Canada — see getTimezoneFromPhone for area code override
  '+44':  'Europe/London',
  '+31':  'Europe/Amsterdam',
  '+32':  'Europe/Brussels',
  '+33':  'Europe/Paris',
  '+34':  'Europe/Madrid',
  '+39':  'Europe/Rome',
  '+41':  'Europe/Zurich',
  '+43':  'Europe/Vienna',
  '+45':  'Europe/Copenhagen',
  '+46':  'Europe/Stockholm',
  '+47':  'Europe/Oslo',
  '+48':  'Europe/Warsaw',
  '+49':  'Europe/Berlin',
  '+61':  'Australia/Sydney',
  '+63':  'Asia/Manila',
  '+64':  'Pacific/Auckland',
  '+65':  'Asia/Singapore',
  '+81':  'Asia/Tokyo',
  '+82':  'Asia/Seoul',
  '+86':  'Asia/Shanghai',
  '+91':  'Asia/Kolkata',
  '+971': 'Asia/Dubai',
  '+972': 'Asia/Jerusalem',
};

// US area code → timezone (covers the 4 US time zones)
const US_AREA_TZ = {
  // Eastern (UTC-5/-4)
  ET: ['201','202','203','207','212','215','216','217','219','224','225','228','229','231','234','239','240',
       '248','251','252','253','254','256','267','269','270','272','276','278','281','301','302','304','305',
       '309','313','315','319','321','323','330','336','339','347','351','352','361','380','385','401','404',
       '407','410','412','413','414','419','423','424','425','434','440','443','445','458','464','469','470',
       '478','484','502','513','516','517','518','540','551','561','571','585','586','601','603','606','609',
       '610','614','615','616','617','619','626','630','631','646','651','678','681','689','701','703','704',
       '706','708','716','718','724','727','731','732','734','740','743','754','757','762','770','772','774',
       '781','786','803','804','810','812','813','814','828','843','845','848','850','856','857','859','860',
       '862','863','864','865','878','901','904','908','910','912','913','914','917','919','920','929','931',
       '937','941','947','954','959','973','978','980','984'],
  // Central (UTC-6/-5)
  CT: ['205','214','218','228','251','254','256','262','270','281','309','312','314','316','318','319','320',
       '325','334','337','361','380','402','405','406','409','417','430','432','469','479','501','504','505',
       '507','512','515','563','573','580','601','608','612','618','620','630','636','641','651','660','662',
       '682','700','712','713','715','731','806','815','816','817','830','832','847','870','901','903','906',
       '913','920','936','940','952','956','972','979','985'],
  // Mountain (UTC-7/-6)
  MT: ['208','303','307','385','406','435','480','505','520','575','602','623','626','682','702','719','720',
       '801','806','928','970'],
  // Pacific (UTC-8/-7)
  PT: ['209','213','310','323','341','360','408','415','424','442','458','503','509','510','530','541','559',
       '562','619','626','650','657','661','669','707','714','747','760','775','805','818','831','858','909',
       '916','925','949','951','971'],
};
const AREA_TO_TZ = {};
US_AREA_TZ.ET.forEach(a => AREA_TO_TZ[a] = 'America/New_York');
US_AREA_TZ.CT.forEach(a => AREA_TO_TZ[a] = 'America/Chicago');
US_AREA_TZ.MT.forEach(a => AREA_TO_TZ[a] = 'America/Denver');
US_AREA_TZ.PT.forEach(a => AREA_TO_TZ[a] = 'America/Los_Angeles');

function getTimezoneFromPhone(phone) {
  // For US/Canada (+1), use area code for precise timezone
  if (phone.startsWith('+1') && phone.length >= 5) {
    const areaCode = phone.slice(2, 5);
    if (AREA_TO_TZ[areaCode]) return AREA_TO_TZ[areaCode];
    return 'America/New_York'; // fallback to ET if area code unknown
  }
  // Try longest prefix first (e.g. +971 before +97)
  const prefixes = Object.keys(COUNTRY_CODE_TZ).sort((a, b) => b.length - a.length);
  for (const prefix of prefixes) {
    if (phone.startsWith(prefix)) return COUNTRY_CODE_TZ[prefix];
  }
  return null;
}

function checkCallingHours(phone) {
  const tz = getTimezoneFromPhone(phone);
  if (!tz) return { allowed: true, reason: 'Unknown timezone — proceeding', tz: 'Unknown', localTime: null };

  const now = new Date();
  const localTime = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    hour: 'numeric',
    minute: '2-digit',
    hour12: false,
    weekday: 'long',
  }).formatToParts(now);

  const parts = {};
  localTime.forEach(p => { parts[p.type] = p.value; });
  const hour = parseInt(parts.hour);
  const weekday = parts.weekday;
  const timeStr = `${parts.hour}:${parts.minute} (${weekday})`;

  const isWeekend = weekday === 'Saturday' || weekday === 'Sunday';
  const inHours = hour >= 8 && hour < 20;

  if (isWeekend) return { allowed: false, reason: `Weekend in ${tz} — it is ${timeStr}. Call Mon–Fri only.`, tz, localTime: timeStr };
  if (!inHours)  return { allowed: false, reason: `Outside calling hours in ${tz} — it is ${timeStr}. Call between 08:00–20:00 only.`, tz, localTime: timeStr };

  return { allowed: true, tz, localTime: timeStr, reason: `OK — ${timeStr} in ${tz}` };
}

