// ── AI: suggest target audiences for a campaign ───────────────────────────
app.post('/api/campaigns/suggest-audiences', async (req, res) => {
  const { service, city, accountType } = req.body || {};
  if (!service) return res.status(400).json({ error: 'service required' });
  try {
    const prompt = accountType === 'contentscale'
      ? `You are a B2B lead generation expert. For ContentScale, an SEO content agency, list 6 types of local businesses in "${city||'any city'}" that would benefit from SEO content services related to "${service}". Format as JSON array: [{"type":"Roofing contractors","why":"They depend on Google for emergency calls but have thin websites","hook":"You're a roofer but Google can't find you — competitors with more pages are taking your calls","searchQuery":"roofing contractors ${city||''}"}]. Only JSON, no markdown.`
      : `You are a lead generation expert. For a business offering "${service}" in "${city||'any city'}", list 6 target audiences who would be ideal to call. Format as JSON array: [{"type":"Homeowners","why":"They own the property and make the decision","hook":"We're working in your neighbourhood this month and offer a free inspection","searchQuery":"homeowners ${city||''}"}]. Only JSON, no markdown.`;

    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': process.env.ANTHROPIC_API_KEY||'', 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 1000, messages: [{ role: 'user', content: prompt }] }),
    });
    const d = await r.json();
    const text = d.content?.[0]?.text || '[]';
    const clean = text.replace(/```json|```/g,'').trim();
    const audiences = JSON.parse(clean);
    res.json({ audiences });
  } catch(e) { res.status(500).json({ error: e.message, audiences: [] }); }
});

